import subprocess, random, itertools

INF=10**9
def parse_ranges(s):
    out=[]
    for part in s.split(","):
        if "-" not in part:
            v=int(part); out.append((v,v))
        elif part.startswith("-"):
            v=int(part[1:]); out.append((1,v))
        elif part.endswith("-"):
            v=int(part[:-1]); out.append((v,INF))
        else:
            a,b=part.split("-"); out.append((int(a),int(b)))
    return out

def predict(s, n=10):
    out=[] # list of [low,high]
    for (lo,hi) in parse_ranges(s):
        new=[lo,hi]
        # iterate existing
        for e in out:
            # comparison based on current new lo? assume yes
            if new[0] > e[0]:
                if new[0] <= e[1]:
                    new[0]=e[1]+1
            else:
                if e[0] <= new[1]:
                    e[0]=new[1]+1
            # what if new empty? still continue?
        out=[e for e in out if e[0]<=e[1]]
        if new[0]<=new[1]:
            out.append(new)
    res=[]
    seen=set()
    for lo,hi in out:
        hi=min(hi,n)
        for i in range(lo,hi+1):
            if i not in seen:
                res.append(i); seen.add(i)
    return res

def actual(s, n=10):
    inp=(" ".join(str(i) for i in range(1,n+1))+"\n").encode()
    p=subprocess.run(["./executable","-f",s], input=inp, capture_output=True)
    if p.returncode!=0:
        return f"ERR {p.stderr!r}"
    txt=p.stdout.decode().strip()
    if not txt: return []
    return [int(x) for x in txt.split("\t")]

# systematic pairs and triples from a pool
pool=["1","2","5","1-3","2-5","4-7","3-3","-4","-7","3-","6-","1-10","2-2","5-9"]
bad=0; tot=0
for a,b in itertools.product(pool, repeat=2):
    s=f"{a},{b}"
    tot+=1
    pr=predict(s); ac=actual(s)
    if pr!=ac:
        bad+=1
        print("MISMATCH pair",s,"pred",pr,"act",ac)
        if bad>30: break
print("pairs done bad",bad,"tot",tot)

bad=0; tot=0
for a,b,c in itertools.product(pool, repeat=3):
    # limit random?
    if tot>800: break
    # use systematic but break early?
    s=f"{a},{b},{c}"
    tot+=1
    pr=predict(s); ac=actual(s)
    if pr!=ac:
        bad+=1
        print("MISMATCH triple",s,"pred",pr,"act",ac)
        if bad>30: break
print("triples sample done bad",bad,"tot",tot)
PY"}

