import subprocess, itertools

INF=10**9
def parse_ranges(s):
    out=[]
    for part in s.split(","):
        if "-" not in part:
            v=int(part); out.append([v,v])
        elif part.startswith("-"):
            v=int(part[1:]); out.append([1,v])
        elif part.endswith("-"):
            v=int(part[:-1]); out.append([v,INF])
        else:
            a,b=part.split("-"); out.append([int(a),int(b)])
    return out

def emit(ranges,n=10):
    res=[]; seen=set()
    for lo,hi in ranges:
        if lo>hi: continue
        for i in range(lo, min(hi,n)+1):
            if i not in seen:
                seen.add(i); res.append(i)
    return res

def adjust(A,B):
    # A is earlier in original order, B later; mutate in place as per pair rule
    if B[0] > A[0]:
        if B[0] <= A[1]:
            B[0]=A[1]+1
    else:
        if A[0] <= B[1]:
            A[0]=B[1]+1

# Models take list of ranges return ranges
def m_adj_fwd(R):
    for i in range(len(R)-1): adjust(R[i],R[i+1])
    return R
def m_adj_rev(R):
    for i in range(len(R)-2,-1,-1): adjust(R[i],R[i+1])
    return R
def m_adj_repeat(R):
    for _ in range(20):
        R=[r for r in R if r[0]<=r[1]]
        changed_before=[tuple(r) for r in R]
        for i in range(len(R)-1): adjust(R[i],R[i+1])
        if [tuple(r) for r in R]==changed_before: break
    return R
def m_pairwise_ij(R):
    # for i<j in lexico
    for i in range(len(R)):
        for j in range(i+1,len(R)): adjust(R[i],R[j])
    return R
def m_insertion_fwd(R_input):
    out=[]
    for r in R_input:
        new=r[:]
        for e in out: adjust(e,new)  # e earlier, new later - adjust according to rule comparing new.low vs e.low ??? our adjust defined that
        out=[e for e in out if e[0]<=e[1]]
        if new[0]<=new[1]: out.append(new)
    return out
def m_insertion_rev(R_input):
    out=[]
    for r in R_input:
        new=r[:]
        for e in reversed(out): adjust(e,new)
        out=[e for e in out if e[0]<=e[1]]
        if new[0]<=new[1]: out.append(new)
    return out
def m_pairwise_j_outer(R):
    # for j (later), for i<j : that's same as insertion fwd but without removal between? adjust mutates orig ranges, empty kept
    for j in range(len(R)):
        for i in range(j): adjust(R[i],R[j])
    return R
def m_pairwise_rev_outer(R):
    for j in range(len(R)):
        for i in range(j-1,-1,-1): adjust(R[i],R[j])
    return R
