import subprocess, itertools, random
INF=10**9
def parse_ranges(s):
 if not s:return []
 out=[]
 for part in s.split(","):
  if "-" not in part: out.append((int(part),int(part)))
  elif part.startswith("-"): out.append((1,int(part[1:])))
  elif part.endswith("-"): out.append((int(part[:-1]),INF))
  else:
   a,b=part.split("-"); out.append((int(a),int(b)))
 return out

def points_priority(R,n):
 assigned=[[] for _ in R]
 for p in range(1,n+1):
  cov=[i for i,(lo,hi) in enumerate(R) if lo<=p<=hi]
  if cov:
   w=min(cov,key=lambda i:(R[i][0],R[i][1],i)); assigned[w].append(p)
 return [x for lst in assigned for x in lst]

def modelA(f,e,n=10):
 R=parse_ranges(f); E=parse_ranges(e)
 pts=points_priority(R,n)
 return tuple(p for p in pts if not any(lo<=p<=hi for lo,hi in E))

def subtract_ranges(R,E):
 # subtract union E from each R, splitting, pieces retain position where range was (subpieces consecutive)
 out=[]
 for lo,hi in R:
  segs=[(lo,hi)]
  for elo,ehi in E:
   new=[]
   for a,b in segs:
    if ehi<a or elo>b: new.append((a,b))
    else:
     if a<elo: new.append((a,elo-1))
     if b>ehi: new.append((ehi+1,b))
   segs=new
  out.extend(segs)
 return out

def modelB(f,e,n=10):
 R=subtract_ranges(parse_ranges(f),parse_ranges(e))
 return tuple(points_priority(R,n))

def actual(f,e,n=10):
 inp=(" ".join(str(i) for i in range(1,n+1))+"\n").encode()
 args=[]
 if f:args+=["-f",f]
 if e:args+=["-e",e]
 p=subprocess.run(["./executable"]+args,input=inp,capture_output=True)
 txt=p.stdout.decode().strip(); return tuple(int(x) for x in txt.split("\t")) if txt else ()

poolF=["1-10","2-8","3-7,1-5","1-5,3-9","5,1-10","2-,2-5","4-6,1-8,3","8-10,2-6","3,2-9"]
poolE=["3","5","2-4","6-8","1","4-6","3,7"]
badA=badB=0
for f,e in itertools.product(poolF,poolE):
 ac=actual(f,e); a=modelA(f,e); b=modelB(f,e)
 if a!=ac:
  badA+=1; print("A mismatch",f,e,"A",a,"B",b,"actual",ac)
 if b!=ac:
  badB+=1
print("badA",badA,"badB",badB)
PY"}

