# simulate span model for examples and compare
INF=10**9
def eff_points(R, excluded,n=6):
 # priority model filtering
 assigned=[[] for _ in R]
 for p in range(1,n+1):
  if p in excluded:continue
  cov=[i for i,(lo,hi) in enumerate(R) if lo<=p<=hi]
  if cov:
   w=min(cov,key=lambda i:(R[i][0],R[i][1],i)); assigned[w].append(p)
 return tuple(x for l in assigned for x in l)
def span_model(groups):
 R=[(min(g),max(g)) for g in groups]
 union=set(x for g in groups for x in g)
 excluded=set(range(1,7))-union
 return eff_points(R,excluded)
def singleton_model(groups):
 R=[(x,x) for g in groups for x in g]
 return eff_points(R,set())
examples=[[(1,4),(3,5)],[(2,4),(1,3)],[(1,3),(2,4)],[(1,3),(2,)],[(2,),(1,3)],[(2,5),(1,3)],[(3,5),(2,6)]]
actual={(1,4):None}
for g in examples:
 print(g,"span",span_model(g),"single",singleton_model(g))
PY"}

