import subprocess, itertools, random
def transform(points):
    # points: sequence of unique ints (dedup first occurrence first)
    seen=[] 
    for p in points:
        if p not in seen:seen.append(p)
    ranges=[] # list [lo,hi]
    for p in seen:
        found=None
        for r in ranges:
            if r[1]+1==p:
                found=r;break
        if found is not None:
            found[1]=p
        else:
            ranges.append([p,p])
    out=[]
    for lo,hi in ranges: out.extend(range(lo,hi+1))
    return tuple(out)
def actual(groups):
    args=["-r"]
    for g in groups:
        pat="^["+"".join("abcdef"[i-1] for i in g)+"]$"; args+=["-F",pat]
    p=subprocess.run(["/tmp/ref_hck"]+args,input=b"a b c d e f\n1 2 3 4 5 6\n",capture_output=True)
    line=p.stdout.decode().splitlines()[0] if p.stdout else ""
    return tuple("abcdef".index(x)+1 for x in line.split("\t")) if line else ()
# two groups random subsets
bad=0; tot=0
subsets=[]
for r in range(1,4):
 for c in itertools.combinations(range(1,7),r): subsets.append(c)
for g1,g2 in itertools.product(subsets,repeat=2):
    tot+=1
    exp=transform(g1+g2)
    ac=actual([g1,g2])
    if exp!=ac:
        bad+=1
        if bad<=20: print("mismatch2",g1,g2,exp,ac)
print("2 groups bad",bad,tot)
# 3 groups random sample from subsets size up to3
random.seed(1); bad=0
for trial in range(150):
    groups=[random.choice(subsets) for _ in range(3)]
    exp=transform(sum(groups,()))
    ac=actual(groups)
    if exp!=ac:
        bad+=1; print("mismatch3",groups,exp,ac)
        if bad>15:break
print("3 groups sample bad",bad)
PY"}

