            Arg::new("crlf")
                .long("crlf")
                .action(ArgAction::SetTrue)
                .help("Support CRLF newlines"),
        )
        .arg(
            Arg::new("INPUT")
                .value_name("INPUT")
                .action(ArgAction::Append)
                .value_parser(clap::value_parser!(PathBuf))
                .help("Input files to parse, defaults to stdin")
                .long_help("Input files to parse, defaults to stdin.\n\nIf a file has a recognizable file extension indicating that it is compressed, and a local binary to perform decompression is found, decompression will occur automagically. This requires with `-z`."),
        )
}

fn parse_opts() -> Opts {
    let m = build_cli().get_matches();
    Opts {
        output: m.get_one::<PathBuf>("output").cloned(),
        delimiter: m.get_one::<String>("delimiter").cloned().unwrap(),
        delim_is_literal: m.get_flag("delim_is_literal"),
        use_input_delim: m.get_flag("use_input_delim"),
        output_delimiter: m.get_one::<String>("output_delimiter").cloned().unwrap(),
        fields: m.get_one::<String>("fields").cloned(),
        exclude: m.get_one::<String>("exclude").cloned(),
        exclude_header: m
            .get_many::<regex::bytes::Regex>("exclude_header")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        header_field: m
            .get_many::<regex::bytes::Regex>("header_field")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
        header_is_regex: m.get_flag("header_is_regex"),
        try_decompress: m.get_flag("try_decompress"),
        try_compress: m.get_flag("try_compress"),
        compression_threads: *m.get_one::<usize>("compression_threads").unwrap(),
        compression_level: *m.get_one::<u32>("compression_level").unwrap(),
        no_mmap: m.get_flag("no_mmap"),
        crlf: m.get_flag("crlf"),
        input: m
            .get_many::<PathBuf>("INPUT")
            .map(|v| v.cloned().collect())
            .unwrap_or_default(),
    }
}

fn fail_log(msg: &str) -> ! {
    error!("{}", msg);
    std::process::exit(1)
}

fn fail_io(err: &io::Error) -> ! {
    error!("{}", err);
    std::process::exit(1)
}

fn unescape_bytes(input: &str) -> Vec<u8> {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'\\' && i + 1 < bytes.len() {
            match bytes[i + 1] {
                b'n' => {
                    out.push(b'\n');
                    i += 2;
                }
                b'r' => {
                    out.push(b'\r');
                    i += 2;
                }
                b't' => {
                    out.push(b'\t');
                    i += 2;
                }
                b'0' => {
                    out.push(0);
                    i += 2;
                }
                b'\\' => {
                    out.push(b'\\');
                    i += 2;
                }
                b'x' => {
                    if i + 3 < bytes.len() + 1 && i + 3 < bytes.len() {
                        // positions i+2 and i+3 must exist; condition rewritten below
                        let _ = 0;
                    }
                    if i + 3 < bytes.len() {
                        if let (Some(h), Some(l)) = (hex_val(bytes[i + 2]), hex_val(bytes[i + 3])) {
                            out.push((h << 4) | l);
                            i += 4;
                        } else {
                            out.push(b'\\');
                            i += 1;
                        }
                    } else if i + 3 == bytes.len() - 0 && false {
                        out.push(b'\\');
                        i += 1;
                    } else {
                        // Need exactly two hex digits; also handle the case where
                        // i+3 is the final valid index.
                        if i + 3 < bytes.len() {
                            unreachable!()
                        }
                        // Re-check with the straightforward bound.
                        if i + 4 <= bytes.len() {
                            if let (Some(h), Some(l)) =
                                (hex_val(bytes[i + 2]), hex_val(bytes[i + 3]))
                            {
                                out.push((h << 4) | l);
                                i += 4;
                            } else {
                                out.push(b'\\');
                                i += 1;
                            }
                        } else {
                            out.push(b'\\');
                            i += 1;
                        }
                    }
                }
                _ => {
                    out.push(b'\\');
                    i += 1;
                }
            }
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    out
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Range {
    low: usize,
    high: usize,
}

fn parse_field_value(s: &str) -> Result<usize, String> {
    match s.parse::<usize>() {
        Ok(0) => Err("Fields and positions are numbered from 1: 0".to_string()),
        Ok(v) => Ok(v),
        Err(_) => Err(format!("Failed to parse field: {}", s)),
    }
}

fn parse_ranges(spec: &str) -> Result<Vec<Range>, String> {
    let mut ranges = Vec::new();
    for token in spec.split(',') {
        if let Some(pos) = token.find('-') {
            let first = &token[..pos];
            let second = &token[pos + 1..];
            if first.is_empty() {
                let high = parse_field_value(second)?;
                ranges.push(Range { low: 1, high });
            } else if second.is_empty() {
                let low = parse_field_value(first)?;
                ranges.push(Range {
                    low,
                    high: usize::MAX,
                });
            } else {
                let low = first
                    .parse::<usize>()
                    .map_err(|_| format!("Failed to parse field: {}", token))?;
                let high = second
                    .parse::<usize>()
                    .map_err(|_| format!("Failed to parse field: {}", token))?;
                if low == 0 {
                    return Err("Fields and positions are numbered from 1: 0".to_string());
                }
                if high < low {
                    return Err(format!(
                        "High end of range less than low end of range: {}-{}",
                        low, high
                    ));
                }
                ranges.push(Range { low, high });
            }
        } else {
            let v = parse_field_value(token)?;
            ranges.push(Range { low: v, high: v });
        }
    }
    Ok(ranges)
}

fn parse_ranges_or_exit(spec: &str) -> Vec<Range> {
    match parse_ranges(spec) {
        Ok(r) => r,
        Err(e) => fail_log(&e),
    }
}

fn ranges_fully_excluded(ranges: &[Range], excludes: &[Range]) -> bool {
    // True iff every point covered by `ranges` is also covered by `excludes`.
    for r in ranges {
        let mut segs: Vec<(u128, u128)> = vec![(r.low as u128, r.high as u128)];
        for e in excludes {
            let (elo, ehi) = (e.low as u128, e.high as u128);
            let mut new_segs = Vec::new();
            for (a, b) in segs {
                if ehi < a || elo > b {
                    new_segs.push((a, b));
                } else {
                    if a < elo {
                        new_segs.push((a, elo - 1));
                    }
                    if b > ehi {
                        new_segs.push((ehi + 1, b));
                    }
                }
            }
            segs = new_segs;
            if segs.is_empty() {
                break;
            }
        }
        if !segs.is_empty() {
            return false;
        }
    }
    true
}

#[derive(Clone, Debug)]
struct Selection {
    ranges: Vec<Range>,
    effective: Vec<Option<Range>>,
    excludes: Vec<Range>,
}

impl Selection {
    fn new(ranges: Vec<Range>, excludes: Vec<Range>) -> Self {
        let effective = compute_effective(&ranges);
        Self {
            ranges,
            effective,
            excludes,
        }
    }

    fn is_empty(&self) -> bool {
        ranges_fully_excluded(&self.ranges, &self.excludes)
    }

    fn excluded(&self, p: usize) -> bool {
        self.excludes.iter().any(|e| e.low <= p && p <= e.high)
    }

    fn selected_indices(&self, n_fields: usize) -> Vec<usize> {
        let mut out = Vec::new();
        for eff in self.effective.iter().flatten() {
            let lo = eff.low.max(1);
            let hi = eff.high.min(n_fields);
            if lo > hi {
                continue;
            }
            for p in lo..=hi {
                if !self.excluded(p) {
                    out.push(p);
                }
            }
        }
        out
    }

    fn first_output_is_field_one(&self) -> bool {
        for eff in self.effective.iter().flatten() {
            let mut p = eff.low;
            loop {
                if p > eff.high {
                    break;
                }
                if let Some(e) = self.excludes.iter().find(|e| e.low <= p && p <= e.high) {
                    if e.high == usize::MAX {
                        p = eff.high;
                        break;
                    } else {
                        p = e.high + 1;
                        continue;
                    }
                }
                return p == 1;
            }
            // This effective range had a non-excluded point handled above by
            // returning; if we are here it had none, so continue.
            if p > eff.high {
                continue;
            }
        }
        false
    }
}

fn compute_effective(ranges: &[Range]) -> Vec<Option<Range>> {
    let mut out = Vec::with_capacity(ranges.len());
    for (i, r) in ranges.iter().enumerate() {
        let mut lo = r.low;
        let mut empty = false;
        for (j, q) in ranges.iter().enumerate() {
            if (q.low, q.high, j) < (r.low, r.high, i) && q.high >= r.low {
                if q.high == usize::MAX {
                    empty = true;
                    break;
                }
                lo = lo.max(q.high + 1);
            }
        }
        if empty || lo > r.high {
            out.push(None);
        } else {
            out.push(Some(Range { low: lo, high: r.high }));
        }
    }
    out
}

enum Splitter {
    Regex(regex::bytes::Regex),
    Substring(Vec<u8>),
    SingleByte(u8),
}

impl Splitter {
    fn split<'a>(&self, line: &'a [u8]) -> Vec<&'a [u8]> {
        match self {
            Splitter::Regex(re) => re.split(line).collect(),
            Splitter::Substring(delim) => {
                if delim.is_empty() {
                    let mut out = Vec::with_capacity(line.len() + 2);
                    out.push(&line[0..0]);
                    for i in 0..line.len() {
                        out.push(&line[i..i + 1]);
                    }
                    out.push(&line[line.len()..line.len()]);
                    out
                } else {
                    let mut out = Vec::new();
                    let mut last = 0usize;
                    for pos in memchr::memmem::find_iter(line, delim) {
                        out.push(&line[last..pos]);
                        last = pos + delim.len();
                    }
                    out.push(&line[last..]);
                    out
                }
            }
            Splitter::SingleByte(b) => {
                let mut out = Vec::new();
                let mut last = 0usize;
                for pos in memchr::memchr_iter(*b, line) {
                    out.push(&line[last..pos]);
                    last = pos + 1;
                }
                out.push(&line[last..]);
                out
            }
        }
    }

    fn is_single_byte(&self) -> Option<u8> {
        if let Splitter::SingleByte(b) = self {
            Some(*b)
        } else {
            None
        }
    }
}

struct Config {
    splitter: Splitter,
    output_delimiter: Vec<u8>,
    crlf: bool,
    fields_spec: Option<String>,
    exclude_spec: Option<String>,
    header_field: Vec<regex::bytes::Regex>,
    exclude_header: Vec<regex::bytes::Regex>,
    header_is_regex: bool,
    try_decompress: bool,
    inputs: Vec<PathBuf>,
}

impl Config {
    fn line_ending(&self) -> &'static [u8] {
        if self.crlf { b"\r\n" } else { b"\n" }
    }
}

fn trim_line_content<'a>(segment: &'a [u8], crlf: bool) -> &'a [u8] {
    if crlf {
        if segment.ends_with(b"\r\n") {
            &segment[..segment.len() - 2]
        } else {
            segment
        }
    } else if segment.ends_with(b"\n") {
        &segment[..segment.len() - 1]
    } else {
        segment
    }
}

fn trim_header_line(line: &str, crlf: bool) -> &str {
    if crlf {
        if let Some(s) = line.strip_suffix("\r\n") {
            s
        } else {
            line
        }
    } else if let Some(s) = line.strip_suffix('\n') {
        s
    } else {
        line
    }
}

// ---------- BGZF writer ----------

fn bgzf_block(data: &[u8], level: u32) -> Vec<u8> {
    use flate2::write::DeflateEncoder;
    let lvl = level.min(9);
    let mut enc = DeflateEncoder::new(Vec::new(), flate2::Compression::new(lvl));
    let _ = enc.write_all(data);
    let compressed = enc.finish().unwrap_or_default();
    let total = 18 + compressed.len() + 8;
    let xfl: u8 = if lvl == 9 {
        2
    } else if lvl < 2 {
        4
    } else {
        0
    };
    let mut out = Vec::with_capacity(total);
    out.extend_from_slice(&[
        0x1f, 0x8b, 0x08, 0x04, 0x00, 0x00, 0x00, 0x00, xfl, 0xff, 0x06, 0x00, b'B', b'C',
        0x02, 0x00,
    ]);
    out.extend_from_slice(&((total - 1) as u16).to_le_bytes());
    out.extend_from_slice(&compressed);
    let mut crc = flate2::Crc::new();
    crc.update(data);
    out.extend_from_slice(&crc.sum().to_le_bytes());
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    out
}

struct BgzfWriter<W: Write> {
    inner: W,
    level: u32,
    threads: usize,
    buffer: Vec<u8>,
    total_in: u64,
    finished: bool,
}

impl<W: Write> BgzfWriter<W> {
    fn new(inner: W, level: u32, threads: usize) -> Self {
        Self {
            inner,
            level,
            threads,
            buffer: Vec::with_capacity(BGZF_BLOCK_SIZE),
            total_in: 0,
            finished: false,
        }
    }

    fn write_block(&mut self, data: &[u8]) -> io::Result<()> {
        let block = bgzf_block(data, self.level);
        self.inner.write_all(&block)
    }

    fn finish_inner(&mut self) -> io::Result<()> {
        if self.finished {
            return Ok(());
        }
        self.finished = true;
        if self.threads <= 1 {
            if !self.buffer.is_empty() {
                let data = std::mem::take(&mut self.buffer);
                self.write_block(&data)?;
                self.inner.write_all(&BGZF_EOF)?;
            }
        } else {
            if !self.buffer.is_empty() {
                let data = std::mem::take(&mut self.buffer);
                self.write_block(&data)?;
            } else if self.total_in == 0 {
                self.write_block(&[])?;
            }
            self.inner.write_all(&BGZF_EOF)?;
        }
        self.inner.flush()
    }

    fn finish_ignore(&mut self) {
        let _ = self.finish_inner();
    }
}

impl<W: Write> Write for BgzfWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.total_in += buf.len() as u64;
        self.buffer.extend_from_slice(buf);
        while self.buffer.len() >= BGZF_BLOCK_SIZE {
            let rest = self.buffer.split_off(BGZF_BLOCK_SIZE);
            let chunk = std::mem::replace(&mut self.buffer, rest);
            self.write_block(&chunk)?;
        }
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        self.inner.flush()
    }
}

impl<W: Write> Drop for BgzfWriter<W> {
    fn drop(&mut self) {
        self.finish_ignore();
    }
}

enum OutWriter {
    Plain(BufWriter<Box<dyn Write>>),
    Gzip(BgzfWriter<BufWriter<Box<dyn Write>>>),
}

impl Write for OutWriter {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            OutWriter::Plain(w) => w.write(buf),
            OutWriter::Gzip(w) => w.write(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            OutWriter::Plain(w) => w.flush(),
            OutWriter::Gzip(w) => w.flush(),
        }
    }
}

impl OutWriter {
    fn finish_for_panic(&mut self) {
        match self {
            OutWriter::Plain(w) => {
                let _ = w.flush();
            }
            OutWriter::Gzip(w) => {
                w.finish_ignore();
            }
        }
    }
}

fn emulate_single_byte_panic(writer: &mut OutWriter) -> ! {
    writer.finish_for_panic();
    let _ = io::stderr().write_all(SINGLE_BYTE_PANIC.as_bytes());
    let _ = io::stderr().flush();
    std::process::exit(101)
}

// ---------- External decompression ----------

struct ExternalReader {
    child: Option<Child>,
    stdout: Option<ChildStdout>,
    stderr_thread: Option<thread::JoinHandle<Vec<u8>>>,
    checked: bool,
}

impl ExternalReader {
    fn spawn(program: &str, args: &[&str], path: &PathBuf) -> io::Result<Self> {
        let mut child = ProcCommand::new(program)
            .args(args)
            .arg(path.as_os_str())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()?;
        let stdout = child.stdout.take();
        let mut stderr_pipe = child.stderr.take();
        let handle = thread::spawn(move || {
            let mut v = Vec::new();
            if let Some(ref mut s) = stderr_pipe {
                let _ = s.read_to_end(&mut v);
            }
            v
        });
        Ok(Self {
            child: Some(child),
            stdout,
            stderr_thread: Some(handle),
            checked: false,
        })
    }

    fn check_status(&mut self) -> io::Result<()> {
        self.checked = true;
        let stderr_bytes = self
            .stderr_thread
            .take()
            .map(|h| h.join().unwrap_or_default())
            .unwrap_or_default();
        let status = if let Some(ref mut child) = self.child {
            child.wait()?
        } else {
            return Ok(());
        };
        self.child = None;
        if status.success() {
            Ok(())
        } else {
            Err(io::Error::new(
                io::ErrorKind::Other,
                format_external_stderr(&stderr_bytes),
            ))
        }
    }
}

impl Read for ExternalReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.checked {
            return Ok(0);
        }
        match self.stdout.as_mut() {
            Some(s) => {
                let n = s.read(buf)?;
                if n == 0 {
                    self.check_status()?;
                }
                Ok(n)
            }
            None => {
                self.check_status()?;
                Ok(0)
            }
        }
    }
}

impl Drop for ExternalReader {
    fn drop(&mut self) {
        if let Some(ref mut child) = self.child {
            let _ = child.kill();
            let _ = child.wait();
        }
        if let Some(h) = self.stderr_thread.take() {
            let _ = h.join();
        }
    }
}

fn format_external_stderr(bytes: &[u8]) -> String {
    if bytes.is_empty() {
        return "<stderr is empty>".to_string();
    }
    let text = String::from_utf8_lossy(bytes);
    let trimmed = text.trim();
    let dashes = "-".repeat(79);
    let mut indented = String::new();
    for (i, line) in trimmed.lines().enumerate() {
        if i > 0 {
            indented.push('\n');
        }
        indented.push_str("    ");
        indented.push_str(line);
    }
    if trimmed.is_empty() {
        indented.push_str("    ");
    }
    format!("\n    {}\n{}\n    {}", dashes, indented, dashes)
}

fn is_executable(path: &PathBuf) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        if let Ok(md) = std::fs::metadata(path) {
            return md.is_file() && (md.permissions().mode() & 0o111) != 0;
        }
        false
    }
    #[cfg(not(unix))]
    {
        std::fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
    }
}

fn find_binary(name: &str) -> bool {
    let Some(paths) = std::env::var_os("PATH") else {
        return false;
    };
    for dir in std::env::split_paths(&paths) {
        let cand = if dir.as_os_str().is_empty() {
            PathBuf::from(name)
        } else {
            dir.join(name)
        };
        if is_executable(&cand) {
            return true;
        }
    }
    false
}

type DynReader = BufReader<Box<dyn Read>>;

fn open_source(path: &PathBuf, config: &Config) -> io::Result<DynReader> {
    if path.as_os_str() == OsStr::new("-") {
        let raw: Box<dyn Read> = if config.try_decompress {
            Box::new(flate2::read::MultiGzDecoder::new(io::stdin()))
        } else {
            Box::new(io::stdin())
        };
        return Ok(BufReader::new(raw));
    }

    if config.try_decompress {
        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
        let external: Option<(&str, Vec<&str>)> = match ext {
            "tgz" | "Z" => Some(("gzip", vec!["-d", "-c"])),
            "bz2" | "tbz2" => Some(("bzip2", vec!["-d", "-c"])),
            "xz" | "txz" => Some(("xz", vec!["-d", "-c"])),
            "lzma" => Some(("xz", vec!["--format=lzma", "-d", "-c"])),
            "zst" | "zstd" => Some(("zstd", vec!["-q", "-d", "-c"])),
            "lz4" => Some(("lz4", vec!["-d", "-c"])),
            "br" => Some(("brotli", vec!["-d", "-c"])),
            _ => None,
        };
        if let Some((program, args)) = external {
            if find_binary(program) {
                let reader = ExternalReader::spawn(program, &args, path)?;
                return Ok(BufReader::new(Box::new(reader) as Box<dyn Read>));
            }
        } else if ext == "gz" {
            let file = std::fs::File::open(path)?;
            let raw: Box<dyn Read> = Box::new(flate2::read::MultiGzDecoder::new(file));
            return Ok(BufReader::new(raw));
        }
    }

    let file = std::fs::File::open(path)?;
    if let Ok(md) = file.metadata() {
        if md.is_dir() {
            #[cfg(unix)]
            {
                return Err(io::Error::from_raw_os_error(21));
            }
        }
    }
    Ok(BufReader::new(Box::new(file) as Box<dyn Read>))
}

// ---------- Header helpers ----------

fn selector_matches(selector: &regex::bytes::Regex, field: &[u8], as_regex: bool) -> bool {
    if as_regex {
        selector.is_match(field)
    } else {
        field == selector.as_str().as_bytes()
    }
}

fn matched_indices(
    selectors: &[regex::bytes::Regex],
    header_fields: &[&[u8]],
    as_regex: bool,
) -> Vec<Vec<usize>> {
    selectors
        .iter()
        .map(|sel| {
            header_fields
                .iter()
                .enumerate()
                .filter_map(|(i, f)| {
                    if selector_matches(sel, f, as_regex) {
                        Some(i + 1)
                    } else {
                        None
                    }
                })
                .collect()
        })
        .collect()
}

fn header_ranges_from_groups(groups: &[Vec<usize>]) -> Vec<Range> {
    let any_multi = groups.iter().any(|g| g.len() > 1);
    if any_multi {
        // Dedup points preserving first occurrence, then build ranges by
        // extending an existing range on the right when possible.
        let mut seen = HashSet::new();
        let mut points: Vec<usize> = Vec::new();
        for g in groups {
            for &p in g {
                if seen.insert(p) {
                    points.push(p);
                }
            }
        }
        let mut ranges: Vec<Range> = Vec::new();
        for p in points {
            if let Some(r) = ranges.iter_mut().find(|r| r.high + 1 == p) {
                r.high = p;
            } else {
                ranges.push(Range { low: p, high: p });
            }
        }
        ranges
    } else {
        let mut ranges = Vec::new();
        for g in groups {
            for &p in g {
                ranges.push(Range { low: p, high: p });
            }
        }
        ranges
    }
}

fn split_header_line<'a>(
    config: &Config,
    content: &'a [u8],
) -> anyhow::Result<Vec<&'a [u8]>> {
    if let Splitter::Substring(delim) = &config.splitter {
        // The reference validates the decoded delimiter as UTF-8 when it
        // splits a header line, surfacing this as an `Error:` failure.
        if let Err(e) = std::str::from_utf8(delim) {
            return Err(anyhow::Error::new(e));
        }
    }
    Ok(config.splitter.split(content))
}

// ---------- Record processing ----------

fn write_record(
    fields: &[&[u8]],
    config: &Config,
    selection: &Selection,
    writer: &mut OutWriter,
) -> io::Result<()> {
    let indices = selection.selected_indices(fields.len());
    for (i, idx) in indices.iter().enumerate() {
        if i > 0 {
            writer.write_all(&config.output_delimiter)?;
        }
        writer.write_all(fields[idx - 1])?;
    }
    writer.write_all(config.line_ending())
}

fn process_segment(
    data: &[u8],
    config: &Config,
    selection: &Selection,
    writer: &mut OutWriter,
) {
    if data.is_empty() {
        return;
    }
    if let Some(b) = config.splitter.is_single_byte() {
        if b == b'\n' {
            if data == b"\n" {
                // one empty record
                if let Err(e) = write_record(&[b""], config, selection, writer) {
                    fail_io(&e);
                }
                return;
            } else {
                let err: io::Error = io::ErrorKind::InvalidData.into();
                fail_io(&err);
            }
        }
        if data.last() != Some(&b'\n') {
            let err: io::Error = io::ErrorKind::InvalidData.into();
            fail_io(&err);
        }
        if data.first() == Some(&b) && selection.first_output_is_field_one() {
            emulate_single_byte_panic(writer);
        }
    }

    let mut start = 0usize;
    while start < data.len() {
        let (segment, next) = if let Some(pos) = memchr::memchr(b'\n', &data[start..]) {
            let end = start + pos + 1;
            (&data[start..end], end)
        } else {
            (&data[start..], data.len())
        };
        let content = trim_line_content(segment, config.crlf);
        let fields = config.splitter.split(content);
        if let Err(e) = write_record(&fields, config, selection, writer) {
            fail_io(&e);
        }
        start = next;
    }
}

fn read_all_or_exit(reader: &mut DynReader) -> Vec<u8> {
    let mut v = Vec::new();
    if let Err(e) = reader.read_to_end(&mut v) {
        fail_io(&e);
    }
    v
}

fn build_combined_ranges(
    fields_opt: &Option<Vec<Range>>,
    header_groups: Option<&Vec<Vec<usize>>>,
    has_header_selectors: bool,
) -> Vec<Range> {
    match (fields_opt, header_groups) {
        (Some(f), Some(groups)) => {
            let mut ranges = f.clone();
            ranges.extend(header_ranges_from_groups(groups));
            ranges
        }
        (Some(f), None) => f.clone(),
        (None, Some(groups)) => header_ranges_from_groups(groups),
        (None, None) => {
            if has_header_selectors {
                vec![Range {
                    low: 1,
                    high: usize::MAX,
                }]
            } else {
                vec![Range {
                    low: 1,
                    high: usize::MAX,
                }]
            }
        }
    }
}

fn main() -> anyhow::Result<()> {
    env_logger::init();
    let opts = parse_opts();

    // Open the output first (errors here are reported via `Error:`).
    let raw_out: Box<dyn Write> = match &opts.output {
        None => Box::new(io::stdout()),
        Some(p) if p.as_os_str() == OsStr::new("-") => Box::new(io::stdout()),
        Some(p) => Box::new(
            std::fs::File::create(p)
                .with_context(|| format!("Failed to open {} for writing.", p.display()))?,
        ),
    };
    let buffered = BufWriter::new(raw_out);
    let mut writer = if opts.try_compress {
        OutWriter::Gzip(BgzfWriter::new(
            buffered,
            opts.compression_level,
            opts.compression_threads,
        ))
    } else {
        OutWriter::Plain(buffered)
    };

    // Build the delimiter splitter (regex compile errors via `Error:`).
    let decoded_literal: Option<Vec<u8>> = if opts.delim_is_literal {
        Some(unescape_bytes(&opts.delimiter))
    } else {
        None
    };
    let splitter: Splitter = if opts.delim_is_literal {
        if opts.delimiter.as_bytes().len() == 1 && !opts.crlf {
            Splitter::SingleByte(opts.delimiter.as_bytes()[0])
        } else {
            Splitter::Substring(decoded_literal.clone().unwrap())
        }
    } else {
        Splitter::Regex(regex::bytes::Regex::new(&opts.delimiter)?)
    };

    let output_delimiter: Vec<u8> = if opts.use_input_delim && opts.delim_is_literal {
        decoded_literal.clone().unwrap()
    } else {
        unescape_bytes(&opts.output_delimiter)
    };

    let config = Config {
        splitter,
        output_delimiter,
        crlf: opts.crlf,
        fields_spec: opts.fields.clone(),
        exclude_spec: opts.exclude.clone(),
        header_field: opts.header_field.clone(),
        exclude_header: opts.exclude_header.clone(),
        header_is_regex: opts.header_is_regex,
        try_decompress: opts.try_decompress,
        inputs: if opts.input.is_empty() {
            vec![PathBuf::from("-")]
        } else {
            opts.input.clone()
        },
    };

    let has_header_field = !config.header_field.is_empty();
    let has_exclude_header = !config.exclude_header.is_empty();
    let has_any_header = has_header_field || has_exclude_header;

    // When no header-field selectors are present, field/exclude specs are
    // validated up front.
    let mut pre_fields: Option<Vec<Range>> = None;
    let mut pre_excludes: Vec<Range> = Vec::new();
    if !has_header_field {
        if let Some(spec) = &config.fields_spec {
            pre_fields = Some(parse_ranges_or_exit(spec));
        }
        if let Some(spec) = &config.exclude_spec {
            pre_excludes = parse_ranges_or_exit(spec);
        }
        if !has_any_header {
            let ranges = build_combined_ranges(&pre_fields, None, false);
            let selection = Selection::new(ranges, pre_excludes.clone());
            if selection.is_empty() {
                return Ok(());
            }
        }
    }

    // Lazily parsed (header-field mode) specs, filled after the first
    // source is opened / its header matched.
    let mut late_fields: Option<Option<Vec<Range>>> = None;
    let mut late_excludes: Option<Vec<Range>> = None;

    for input_path in &config.inputs {
        let mut reader = match open_source(input_path, &config) {
            Ok(r) => r,
            Err(e) => fail_io(&e),
        };

        if has_header_field {
            // Field specs are validated after opening the source.
            if late_fields.is_none() {
                let parsed = config
                    .fields_spec
                    .as_deref()
                    .map(|s| parse_ranges_or_exit(s));
                late_fields = Some(parsed);
            }
            let fields_opt = late_fields.clone().unwrap();

            // Read the header line.
            let mut line = String::new();
            let nread = match reader.read_line(&mut line) {
                Ok(n) => n,
                Err(e) => fail_io(&e),
            };
            let header_content: Option<Vec<u8>> = if nread == 0 {
                None
            } else {
                Some(trim_header_line(&line, config.crlf).as_bytes().to_vec())
            };
            let header_fields: Vec<&[u8]> = match &header_content {
                Some(content) => split_header_line(&config, content)?,
                None => Vec::new(),
            };
            // Need owned slices' data alive: header_content lives in this scope.
            let groups = matched_indices(&config.header_field, &header_fields, config.header_is_regex);
            if groups.iter().all(|g| g.is_empty()) {
                fail_log("No headers matched");
            }
            for (sel, g) in config.header_field.iter().zip(groups.iter()) {
                if g.is_empty() {
                    fail_log(&format!("Header not found: {}", sel.as_str()));
                }
            }

            if late_excludes.is_none() {
                let parsed = config
                    .exclude_spec
                    .as_deref()
                    .map(|s| parse_ranges_or_exit(s))
                    .unwrap_or_default();
                late_excludes = Some(parsed);
            }
            let mut excludes = late_excludes.clone().unwrap();
            if has_exclude_header {
                let egroups = matched_indices(
                    &config.exclude_header,
                    &header_fields,
                    config.header_is_regex,
                );
                for g in &egroups {
                    for &p in g {
                        excludes.push(Range { low: p, high: p });
                    }
                }
            }

            let ranges = build_combined_ranges(&fields_opt, Some(&groups), true);
            let selection = Selection::new(ranges, excludes);
            if selection.is_empty() {
                continue;
            }

            if let Some(content) = &header_content {
                if !content.is_empty() {
                    if let Err(e) = write_record(&header_fields, &config, &selection, &mut writer) {
                        fail_io(&e);
                    }
                }
            }

            let data = read_all_or_exit(&mut reader);
            process_segment(&data, &config, &selection, &mut writer);
        } else if has_exclude_header {
            let fields_opt = pre_fields.clone();
            let mut line = String::new();
            let nread = match reader.read_line(&mut line) {
                Ok(n) => n,
                Err(e) => fail_io(&e),
            };
            let header_content: Option<Vec<u8>> = if nread == 0 {
                None
            } else {
                Some(trim_header_line(&line, config.crlf).as_bytes().to_vec())
            };
            let header_fields: Vec<&[u8]> = match &header_content {
                Some(content) => split_header_line(&config, content)?,
                None => Vec::new(),
            };
            let mut excludes = pre_excludes.clone();
            let egroups = matched_indices(
                &config.exclude_header,
                &header_fields,
                config.header_is_regex,
            );
            for g in &egroups {
                for &p in g {
                    excludes.push(Range { low: p, high: p });
                }
            }
            let ranges = build_combined_ranges(&fields_opt, None, true);
            let selection = Selection::new(ranges, excludes);
            if selection.is_empty() {
                continue;
            }
            if let Some(content) = &header_content {
                if !content.is_empty() {
                    if let Err(e) = write_record(&header_fields, &config, &selection, &mut writer) {
                        fail_io(&e);
                    }
                }
            }
            let data = read_all_or_exit(&mut reader);
            process_segment(&data, &config, &selection, &mut writer);
        } else {
            let ranges = build_combined_ranges(&pre_fields, None, false);
            let selection = Selection::new(ranges, pre_excludes.clone());
            // (emptiness was handled globally above)
            let data = read_all_or_exit(&mut reader);
            process_segment(&data, &config, &selection, &mut writer);
        }
    }

    drop(writer);
    Ok(())
}
RS"}

