    let mut built: Vec<Range> = Vec::new();
    for r in ranges {
        if let Some(b) = built
            .iter_mut()
            .find(|b| b.high != usize::MAX && b.high + 1 == r.low)
        {
            b.high = r.high;
        } else {
            built.push(r);
        }
    }
    built
}

fn combine_fields_and_headers(fields: &[Range], groups: &[Vec<usize>]) -> Vec<Range> {
    let mut ranges: Vec<Range> = fields.to_vec();
    let header_points: Vec<usize> = groups.iter().flatten().copied().collect();
    for (idx, p) in header_points.iter().enumerate() {
        let nr = Range { low: *p, high: *p };
        if idx == 0 {
            if ranges.is_empty() {
                ranges.push(nr);
            } else if nr.low < ranges[0].low {
                ranges.insert(0, nr);
            } else {
                let at = 1.min(ranges.len());
                ranges.insert(at, nr);
            }
        } else if let Some(r) = ranges
            .iter_mut()
            .find(|r| r.high != usize::MAX && r.high + 1 == nr.low)
        {
            r.high = nr.high;
        } else {
            ranges.push(nr);
        }
    }
    if fields.len() <= 2 {
        ranges = right_extend_build(ranges);
    }
    ranges
}

fn build_combined_ranges(
    fields_opt: &Option<Vec<Range>>,
    header_groups: Option<&Vec<Vec<usize>>>,
    has_header_selectors: bool,
) -> Vec<Range> {
    match (fields_opt, header_groups) {
        (Some(f), Some(groups)) => combine_fields_and_headers(f, groups),
        (Some(f), None) => f.clone(),
        (None, Some(groups)) => header_ranges_from_groups(groups),
        (None, None) => {
            let _ = has_header_selectors;
            vec![Range {
                low: 1,
                high: usize::MAX,
            }]
        }
    }
}

